#' Derive an analysis-ready data set listing viral loads (VL)
#'
#' @param missing_result Numeric value (including NA_integer_) to impute for the
#'   result when (1) the person's VL records for that date are *all* missing a
#'   value for result *and* (2) some have an interpretation of '<' or 'ND' and
#'   none have an interpretation of '>'.
#' @param cache Whether to use or overwrite cached results. Must be one of 'use'
#'   (the default), 'overwrite', or 'ignore'. If cache = 'use' (the default) and
#'   a dataset was generated by a previous call to this function *using the same
#'   parameters* and the same eHARS data and was cached, the cached dataset is
#'   returned, otherwise a dataset is derived and cached. If cache =
#'   'overwrite', a dataset is (re-)derived and (re-)cached, overwriting any
#'   existing analogous dataset in the cache. If cache = 'ignore', a dataset is
#'   re-derived but not (re-)cached.
#'
#' @returns A data.frame unique by stateno + sample_dt_char (i.e., the original
#'   value in lab.sample_dt). Contains variables sample_dt (Date; .. imputed as
#'   15 and .... imputed as 0630), max_result_unimputed (num), result (num;
#'   equals `missing_result` under the conditions specified above, otherwise
#'   equals max_result_unimputed), result_interpretation (chr; 'I' and '=' are
#'   omitted), first_enter_dt (Date; earliest enter_dt for any document with a
#'   VL with this stateno + sample_dt), document_uid, and facility (chr).
#'
#' @details The cached dataset is stored in the "/Derived" subdirectory of the
#'   date-specific folder containing the eHARS datasets. If no such directory
#'   exists when this function is called, it creates it.
#'
#' @export
#' @importFrom data.table ":=" set fcase
#'
#' @examples
#' if(FALSE){
#' vls <- get_VLs()
#' }

get_VLs <- function(
  missing_result = 199,
  cache = "use"
) {
  stopifnot(is.numeric(missing_result))
  stopifnot(cache %in% c("use", "ignore", "overwrite"))

  if (cache == "use") {
    # check if a cached dataset generated by a previous run using the same
    # parameters already exists and, if so, read it in and return it
    cache_file_path <- construct_cache_file_path() # NOTE: cannot simpl
    if (file.exists(cache_file_path)) {
      return(readRDS(cache_file_path))
    }
  }

  VLs0a <- read_ehars_doc(
    "lab",
    col_select = c(
      "document_uid",
      "sample_dt",
      "facility_uid",
      "lab_test_cd",
      "result",
      "result_units",
      "result_interpretation"
    )
  ) |>
    dplyr::filter(
      lab_test_cd %in%
        c(
          'EC-060', # HIV-1 RNA/DNA NAAT (Quantitative)
          'EC-061', # HIV-2 RNA/DNA NAAT (Quantitative)
          'EC-014', # HIV-1 RNA/DNA NAAT (Quantitative viral load)'
          'EC-015', # HIV-2 RNA/DNA NAAT (Quantitative viral load)'
          'L-010', # Viral Load-Other-Legacy'
          'L-011' # Viral Load-Unspecified-Legacy'
        )
    ) |>
    dplyr::left_join(
      read_ehars_doc(
        "document",
        col_select = c("document_uid", "ehars_uid", "enter_dt")
      ),
      by = "document_uid"
    ) |>
    dplyr::left_join(
      read_ehars_person(col_select = c("stateno", "ehars_uid")),
      by = "ehars_uid"
    )

  # where a HIV-1 RNA NAAT (Qualitative AND Quantitative) test done, the QUAL
  # result is stored in document.lab with EC-058  and the QUANT result is stored
  # in document.lab_ANALYTE with EC-059; so need to pull VLs from
  # document.lab_ANALYTE as well to combine with the above

  VLs0b <- read_ehars_doc(
    "lab_analyte",
    col_select = c(
      "document_uid",
      "lab_seq",
      "lab_test_cd",
      "result",
      "result_units",
      "result_interpretation"
    )
  ) |>
    dplyr::filter(
      lab_test_cd == 'EC-059'
    )

  # as of 10/16/2026, no quantitative VLs stored in document.lab_analyte; if
  # still none, skip subsequent expensive join operations
  if (nrow(VLs0b) > 0) {
    VLs0b <- VLs0b |>
      dplyr::left_join(
        read_ehars_doc(
          "lab",
          col_select = c(
            "document_uid",
            "lab_seq",
            "sample_dt",
            "facility_uid",
            "provider_uid"
          )
        ),
        by = dplyr::join_by(document_uid, lab_seq)
      ) |>
      dplyr::left_join(
        read_ehars_doc(
          "document",
          col_select = c("document_uid", "ehars_uid", "enter_dt")
        ),
        by = "document_uid"
      ) |>
      dplyr::left_join(
        read_ehars_person(col_select = c("stateno", "ehars_uid")),
        by = "ehars_uid"
      )
  } else {
    VLs0b <- VLs0b |>
      dplyr::mutate(
        stateno = '',
        sample_dt = '',
        facility_uid = '',
        lab_test_cd,
        result,
        result_units,
        result_interpretation,
        enter_dt = '',
        document_uid
      )
  }

  # combine data ----
  vars <- c(
    'stateno',
    'sample_dt',
    'facility_uid',
    'result',
    'result_units',
    'result_interpretation',
    'enter_dt',
    'document_uid'
  )

  VLs0 <- rbind(
    VLs0a |> dplyr::select(all_of(vars)),
    VLs0b |> dplyr::select(all_of(vars))
  ) |>
    dplyr::distinct() |>
    dplyr::filter(!sample_dt %in% c('', '........'))

  stopifnot(all(
    VLs0$result_interpretation %in%
      c('<', '>', 'ND', 'I', '=', '', NA_character_)
  ))

  # get facility_name ----
  VLs1 <- VLs0 |>
    dplyr::left_join(
      read_ehars_doc("facility_code", col_select = c("facility_uid", "name1")),
      by = "facility_uid"
    ) |>
    dplyr::rename(facility = name1) |>
    dplyr::select(-facility_uid)

  # initial calcs ----
  VLs2 <- VLs1 |>
    dtplyr::lazy_dt() |>
    dplyr::mutate(
      sample_dt_char = sample_dt,
      sample_dt = ehars_dt.as.Date(sample_dt),
      enter_dt = ehars_dt.as.Date(enter_dt),
      result_raw = result,
      result = dplyr::case_when(
        result_units == 'LOG' ~ 10^(result |>
          stringr::str_remove_all("[^0-9\\.]") |>
          as.numeric()),
        TRUE ~ result |> stringr::str_remove_all("[^0-9\\.]") |> as.numeric()
      ),
      result_interpretation = result_interpretation |>
        dplyr::replace_when(
          !result_interpretation %in% c('<', '>', 'ND') ~ NA_character_,
          result_interpretation == 'ND' ~ '-ND' # ensures desired sort order: '(-)ND' < '<' < '>'
        )
    ) |>
    dplyr::as_tibble()

  # summarize by stateno + sample_dt ----
  VLs3 <- VLs2 |>
    dtplyr::lazy_dt() |>
    # NOTE: the above enables the dtplyr package to automatically translate
    # dplyr pipelines into highly optimized data.table code behind the scenes
    dplyr::summarize(
      .by = c("stateno", "sample_dt_char"),
      sample_dt = max(sample_dt, na.rm = TRUE),
      max_result_unimputed = max(result, na.rm = TRUE),
      result_interpretation = max(result_interpretation, na.rm = TRUE),
      first_enter_dt = min(enter_dt, na.rm = TRUE),
      document_uid = paste(unique(document_uid), collapse = ", "),
      facility = unique(na.omit(facility)) |> paste(collapse = ", ")
    ) |>
    dplyr::as_tibble()

  # update result and result_interpretation ----
  VLs4 <- VLs3 |>
    dplyr::mutate(
      result = dplyr::case_when(
        max_result_unimputed == -Inf & # b/c when no non-missing arguments to max(), -Inf returned
          result_interpretation %in% c('<', '-ND') ~ missing_result,
        max_result_unimputed == -Inf ~ NA,
        TRUE ~ max_result_unimputed
      ) |>
        Misc.SHH.f::set_notes_attr(
          paste(
            'Imputed as',
            missing_result,
            "when (1) the person's VL records for that date are *all* missing a value for result *and* (2) some have an interpretation of '<' or 'ND' and none have an interpretation of '>'"
          )
        ),
      max_result_unimputed = max_result_unimputed |>
        dplyr::replace_when(max_result_unimputed == -Inf ~ NA),
      result_interpretation = result_interpretation |>
        dplyr::replace_when(result_interpretation == '-ND' ~ 'ND')
    ) |>
    dplyr::select(
      stateno,
      sample_dt_char,
      sample_dt,
      max_result_unimputed,
      result,
      result_interpretation,
      first_enter_dt,
      document_uid,
      facility
    )

  Misc.SHH.f::assert_unique(df = VLs4, by = c("stateno", "sample_dt_char"))

  write_to_cache(x = VLs4, cache = cache)

  return(VLs4)
}

